test("one valid action between refusals resets consecutiveRefusals and actor ultimately produces a verified candidate", async () => {
  const territory = fixture(), ledgerRoot = join(territory, "trajectory-ledger");
  let wave = 0;
  const dispatch = async (jobs) => {
    wave += 1;
    if (wave === 1) return jobs.map((job) => ({ id: job.id, refusal: { type: "no-feasible-endpoint" }, attempts: [] }));
    if (wave === 2) return jobs.map((job) => response(job, { action: "read", args: { path: "calc.mjs" }, reason: "inspect before editing" }));
    if (wave === 3) return jobs.map((job) => ({ id: job.id, refusal: { type: "no-feasible-endpoint" }, attempts: [] }));
    return jobs.map((job) => response(job, {
      action: "edit",
      args: { path: "calc.mjs", blocks: "<<<<<<< SEARCH\nexport const add = (a, b) => a - b;\n=======\nexport const add = (a, b) => a + b;\n>>>>>>> REPLACE" },
      reason: "fix addition",
    }));
  };
  const result = await runMission({
    id: "urn:test:mission:refusal-reset",
    objective: "Repair the add function so the declared test passes.",
    territory,
    verifyCommand: "node --test calc.test.mjs",
    actors: 1,
    maxRounds: 5,
    maxConsecutiveRefusals: 2,
    apply: false,
  }, { dispatch, ledgerRoot });

  assert.equal(result.outcome.verified, true);
  assert.equal(result.metrics.rounds, 4);
  assert.equal(wave, 4);
  assert.equal(result.actors[0].status, "verified");
});"}]},"reason":"Add refusal-reset regression test: wave1=refusal, wave2=valid read, wave3=refusal, wave4=valid edit; with maxConsecutiveRefusals=2 the actor never trips the circuit and produces a verified candidate in round 4"}]}]

